#!/usr/bin/env bash
# Tests for pm-dashboard-backup.sh's expected-set manifest (#1025,
# design #1024 phase 2):
#   the manifest used to be generated by walking the staging tree, so
#   the archive verify step could only prove the archive matched
#   whatever staging produced — a dataset member deleted/renamed at
#   the source silently shrank the backup set with every check green.
#   The script now declares the expected set once (EXPECTED_SET):
#   12 aggregator state files are REQUIRED (decisions.json and
#   decision-events.jsonl since #10293), meta-quota-export files are
#   OPTIONAL, db-dumps and the Turso store exports are
#   required when their step ran (optional when it did not). The
#   snapshots tree + 2 journal logs are OPTIONAL.
#   manifest.json records every member's status, and the verify step
#   fails the run — naming the member, before any upload, cursor
#   unchanged — when a required member is missing.
# This drives the REAL script with stubbed tools (the
# pm-dashboard-backup.test.sh harness shape): scratch HOME, stub bws,
# stub journalctl, stub rclone backed by a local store. Scenarios:
#   * deleted-required — registry.json deleted at the source: run
#     fails, FAILED line names aggregator/registry.json, nothing
#     uploaded, cursor unchanged, and the built archive's manifest
#     records the member as required + missing.
#   * missing-optional — snapshots tree (and db-dumps, dump step not
#     run) absent: run completes, uploads, cursor advances, and
#     manifest.json records both members as optional + missing with
#     every required member present.
#   * dump-ran-no-dir — the dump step ran (stub script, exit 0) but
#     produced no dumps dir: db-dumps is conditionally REQUIRED, so
#     the run fails naming db-dumps, cursor unchanged.
#   * dump-ran-with-dir — the dump step produced its dir: the staged
#     db-dumps member is recorded required + present, run completes.
set -uo pipefail

SELF_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
if [[ -f "$SELF_DIR/pm-dashboard-backup.sh" ]]; then
  SCRIPT="$SELF_DIR/pm-dashboard-backup.sh"
else
  SCRIPT="$SELF_DIR/modules/pm-dashboard-backup.sh"
fi

TMP_ROOT="$(mktemp -d)"
trap 'rm -rf "$TMP_ROOT"' EXIT

failures=0
fail() {
  echo "FAIL: $1" >&2
  failures=$((failures + 1))
}
ok() { echo "ok: $1"; }

BIN="$TMP_ROOT/bin"
mkdir -p "$BIN"

{
  printf '#!%s\n' "$BASH"
  cat <<'STUB'
if [[ "${1:-} ${2:-}" == "secret list" ]]; then
  printf '%s\n' '[{"key":"cloudflare.r2-backups-access-key-id","value":"fake-access-key-id"},{"key":"cloudflare.r2-backups-secret-access-key","value":"fake-secret-access-key"},{"key":"cloudflare.r2-endpoint","value":"https://example.invalid"}]'
  exit 0
fi
echo "stub bws: unsupported args: $*" >&2
exit 1
STUB
} >"$BIN/bws"

{
  printf '#!%s\n' "$BASH"
  cat <<'STUB'
echo "stub journal line"
printf '%s\n' "$*" >>"$HOME/.journalctl-calls"
exit 0
STUB
} >"$BIN/journalctl"

{
  printf '#!%s\n' "$BASH"
  cat <<'STUB'
store="${RCLONE_STUB_DIR:?RCLONE_STUB_DIR unset}"
calls="${RCLONE_CALLS_LOG:?RCLONE_CALLS_LOG unset}"
mkdir -p "$store"
echo "$*" >>"$calls"
key() { printf '%s' "$1" | tr '/:' '__'; }
cmd="${1:-}"
shift || true
case "$cmd" in
  copyto) cp "$1" "$store/$(key "$2")" ;;
  cat)
    f="$store/$(key "$1")"
    [[ -f "$f" ]] || exit 1
    cat "$f"
    ;;
  lsf) exit 0 ;;
  purge) exit 0 ;;
  *)
    echo "stub rclone: unsupported command: $cmd" >&2
    exit 1
    ;;
esac
STUB
} >"$BIN/rclone"
chmod +x "$BIN/bws" "$BIN/journalctl" "$BIN/rclone"

# dump-step stubs: one that produces its dumps dir, one that does not
DUMPBIN="$TMP_ROOT/dump-bin"
mkdir -p "$DUMPBIN"
{
  printf '#!%s\n' "$BASH"
  cat <<'STUB'
mkdir -p "$HOME/backups/pm-stack/$1"
printf 'dump bytes\n' >"$HOME/backups/pm-stack/$1/dump.sql"
exit 0
STUB
} >"$DUMPBIN/dump-with-dir.sh"
{
  printf '#!%s\n' "$BASH"
  cat <<'STUB'
exit 0
STUB
} >"$DUMPBIN/dump-no-dir.sh"
chmod +x "$DUMPBIN/dump-with-dir.sh" "$DUMPBIN/dump-no-dir.sh"

PRESET=1000000000
RC=0
MARKER_AFTER=""
RUN_HOME=""
DUMP_SCRIPT_ARG=""

setup_home() {
  local name="$1"
  RUN_HOME="$TMP_ROOT/$name/home"
  mkdir -p "$RUN_HOME/backups/dashboard" "$RUN_HOME/.local/state/pm-aggregator" \
    "$RUN_HOME/atlas/meta-quota-export"
  local f
  for f in actions.json comments.json fleet-feed.json quota-current.json \
    registry.json quota-gatherer-state.json quota-gatherer-heartbeat.json \
    events.json coverage-snapshot.json aa-last-good.json \
    decisions.json decision-events.jsonl; do
    printf '{}\n' >"$RUN_HOME/.local/state/pm-aggregator/$f"
  done
  printf '{}\n' >"$RUN_HOME/atlas/meta-quota-export/latest.json"
  printf 'history\n' >"$RUN_HOME/atlas/meta-quota-export/history.jsonl"
  echo "$PRESET" >"$RUN_HOME/backups/dashboard/.last-run-epoch"
  DUMP_SCRIPT_ARG="$RUN_HOME/no-such-dump-script.sh"
}

run_backup() {
  local name="$1"
  shift
  HOME="$RUN_HOME" PATH="$BIN:$PATH" BWS_ACCESS_TOKEN="fake-token" \
    RCLONE_STUB_DIR="$TMP_ROOT/$name/rclone-store" \
    RCLONE_CALLS_LOG="$TMP_ROOT/$name/rclone-calls.log" \
    PM_DB_DUMP_SCRIPT="$DUMP_SCRIPT_ARG" \
    PM_AGG_STORE_EXPORT=off \
    "$@" \
    bash "$SCRIPT" 2026-10-28 >"$TMP_ROOT/$name.log" 2>&1
  RC=$?
  MARKER_AFTER="$(cat "$RUN_HOME/backups/dashboard/.last-run-epoch" 2>/dev/null || echo missing)"
}

manifest_json() { # $1 = scenario name; prints the run's manifest.json
  local arc="$RUN_HOME/backups/dashboard/2026-10-28/dashboard-2026-10-28.tar.zst"
  local d="$TMP_ROOT/$1-manifest"
  mkdir -p "$d"
  tar -I zstd -xf "$arc" -C "$d" ./manifest.json 2>/dev/null
  cat "$d/manifest.json"
}

# assert_member <scenario> <path> <class> <status>
assert_member() {
  if manifest_json "$1" | python3 -c '
import json, sys
m = json.load(sys.stdin)
path, cls, status = sys.argv[1], sys.argv[2], sys.argv[3]
for e in m.get("expected", []):
    if e["path"] == path:
        sys.exit(0 if (e["class"] == cls and e["status"] == status) else 1)
sys.exit(1)
' "$2" "$3" "$4"; then
    ok "$1: manifest records $2 as $3 + $4"
  else
    fail "$1: manifest does not record $2 as $3 + $4: $(manifest_json "$1")"
  fi
}

no_upload() { # $1 scenario name
  [[ ! -f "$TMP_ROOT/$1/rclone-calls.log" ]] ||
    ! grep -q '^copyto' "$TMP_ROOT/$1/rclone-calls.log"
}

# --- deleted-required fails the run -----------------------------------------
setup_home deleted-required
rm "$RUN_HOME/.local/state/pm-aggregator/registry.json"
run_backup deleted-required
if [[ $RC -ne 0 ]]; then
  ok "deleted-required: script exited non-zero ($RC)"
else
  fail "deleted-required: expected non-zero exit, got 0; log: $(cat "$TMP_ROOT/deleted-required.log")"
fi
if grep -q 'FAILED required dataset member missing: aggregator/registry.json' "$TMP_ROOT/deleted-required.log"; then
  ok "deleted-required: FAILED line names the missing member"
else
  fail "deleted-required: no FAILED line naming the member: $(cat "$TMP_ROOT/deleted-required.log")"
fi
if no_upload deleted-required; then
  ok "deleted-required: nothing uploaded"
else
  fail "deleted-required: an upload was attempted"
fi
if [[ $MARKER_AFTER == "$PRESET" ]]; then
  ok "deleted-required: journal marker unchanged"
else
  fail "deleted-required: marker advanced — was $PRESET, now $MARKER_AFTER"
fi
assert_member deleted-required aggregator/registry.json required missing

# --- missing-optional completes and is recorded -------------------------------
setup_home missing-optional
rm -rf "$RUN_HOME/atlas/meta-quota-export"
run_backup missing-optional
if [[ $RC -eq 0 ]]; then
  ok "missing-optional: script exited 0"
else
  fail "missing-optional: expected exit 0, got $RC; log: $(cat "$TMP_ROOT/missing-optional.log")"
fi
if [[ $MARKER_AFTER =~ ^[0-9]+$ ]] && [[ $MARKER_AFTER -gt $PRESET ]]; then
  ok "missing-optional: journal marker advanced"
else
  fail "missing-optional: marker did not advance — was $PRESET, now $MARKER_AFTER"
fi
assert_member missing-optional aggregator/snapshots optional missing
assert_member missing-optional db-dumps optional missing
# The Turso store exports are conditionally required only when the
# export ran (backend=file in this harness, so optional).
assert_member missing-optional turso/agg_actions.json optional missing
assert_member missing-optional turso/orch_runs.json optional missing
assert_member missing-optional aggregator/actions.json required present
assert_member missing-optional meta-quota-export/latest.json optional missing
assert_member missing-optional meta-quota-export/history.jsonl optional missing
assert_member missing-optional journals/pm-aggregator.log optional present
if grep -q -- 'meta-quota-export.service' "$RUN_HOME/.journalctl-calls"; then
  fail "missing-optional: retired meta-quota-export journal was queried"
else
  ok "missing-optional: retired meta-quota-export journal was not queried"
fi
if manifest_json missing-optional | python3 -c '
import json, sys
m = json.load(sys.stdin)
sys.exit(0 if len(m.get("expected", [])) == 48 else 1)
'; then
  ok "missing-optional: manifest lists all 48 expected members"
else
  fail "missing-optional: manifest expected list is not the full 48-member set"
fi

# --- decisions ledger is required (#10293) -----------------------------------
setup_home decisions-deleted
rm "$RUN_HOME/.local/state/pm-aggregator/decisions.json"
run_backup decisions-deleted
if [[ $RC -ne 0 ]] && grep -q 'FAILED required dataset member missing: aggregator/decisions.json' "$TMP_ROOT/decisions-deleted.log"; then
  ok "decisions-deleted: run fails naming aggregator/decisions.json"
else
  fail "decisions-deleted: expected a failed run naming decisions.json, rc=$RC; log: $(cat "$TMP_ROOT/decisions-deleted.log")"
fi
if [[ $MARKER_AFTER == "$PRESET" ]]; then
  ok "decisions-deleted: journal marker unchanged"
else
  fail "decisions-deleted: marker advanced — was $PRESET, now $MARKER_AFTER"
fi
assert_member decisions-deleted aggregator/decisions.json required missing

# --- ledger companions staged; unclassified state named (#10293) ---------------
setup_home ledger-staged
agg="$RUN_HOME/.local/state/pm-aggregator"
printf '{"id":"e1"}\n' >"$agg/decision-events-outbox.jsonl"
printf '{"offset":1}\n' >"$agg/decision-events-outbox.jsonl.sync-state.json"
printf '{}\n' >"$agg/needs-drew.json"
printf '{}\n' >"$agg/needs-user.json"
mkdir -p "$agg/digests"
printf '{}\n' >"$agg/digests/daily-2026-10-27.json"
printf '{}\n' >"$agg/board.json"          # derived: not archived, not flagged
printf '{}\n' >"$agg/events.json.tmp-1-2" # write temp: skipped
printf '{}\n' >"$agg/mystery-state.json"  # nobody classified this one
run_backup ledger-staged
if [[ $RC -eq 0 ]]; then
  ok "ledger-staged: script exited 0"
else
  fail "ledger-staged: expected exit 0, got $RC; log: $(cat "$TMP_ROOT/ledger-staged.log")"
fi
assert_member ledger-staged aggregator/decisions.json required present
assert_member ledger-staged aggregator/decision-events.jsonl required present
assert_member ledger-staged aggregator/decision-events-outbox.jsonl optional present
assert_member ledger-staged aggregator/decision-events-outbox.jsonl.sync-state.json optional present
assert_member ledger-staged aggregator/needs-drew.json optional present
assert_member ledger-staged aggregator/needs-user.json optional present
assert_member ledger-staged aggregator/notifications.jsonl optional missing
assert_member ledger-staged aggregator/digests optional present
if manifest_json ledger-staged | python3 -c '
import json, sys
m = json.load(sys.stdin)
sys.exit(0 if m.get("unclassified") == ["mystery-state.json"] else 1)
'; then
  ok "ledger-staged: manifest names only the unclassified state file"
else
  fail "ledger-staged: manifest unclassified list is wrong: $(manifest_json ledger-staged)"
fi
if grep -q 'WARN unclassified state file .*/mystery-state.json' "$TMP_ROOT/ledger-staged.log"; then
  ok "ledger-staged: log names the unclassified state file"
else
  fail "ledger-staged: no WARN naming the unclassified file: $(cat "$TMP_ROOT/ledger-staged.log")"
fi

# --- dump step ran but produced no dir: conditionally required ----------------
setup_home dump-ran-no-dir
DUMP_SCRIPT_ARG="$DUMPBIN/dump-no-dir.sh"
run_backup dump-ran-no-dir
if [[ $RC -ne 0 ]] && grep -q 'FAILED required dataset member missing: db-dumps' "$TMP_ROOT/dump-ran-no-dir.log"; then
  ok "dump-ran-no-dir: run failed naming db-dumps"
else
  fail "dump-ran-no-dir: expected non-zero + FAILED db-dumps line, got rc=$RC: $(cat "$TMP_ROOT/dump-ran-no-dir.log")"
fi
if [[ $MARKER_AFTER == "$PRESET" ]] && no_upload dump-ran-no-dir; then
  ok "dump-ran-no-dir: marker unchanged, nothing uploaded"
else
  fail "dump-ran-no-dir: marker moved or an upload was attempted"
fi

# --- dump step ran and produced its dir: present + required --------------------
setup_home dump-ran-with-dir
DUMP_SCRIPT_ARG="$DUMPBIN/dump-with-dir.sh"
run_backup dump-ran-with-dir
if [[ $RC -eq 0 ]]; then
  ok "dump-ran-with-dir: script exited 0"
else
  fail "dump-ran-with-dir: expected exit 0, got $RC; log: $(cat "$TMP_ROOT/dump-ran-with-dir.log")"
fi
assert_member dump-ran-with-dir db-dumps required present
assert_member dump-ran-with-dir meta-quota-export/latest.json optional present
assert_member dump-ran-with-dir meta-quota-export/history.jsonl optional present

# --- file backend: remote store export not applicable ---------------------------
# Default PM_AGG_STORE_EXPORT=auto with no $AGG/.env (or a backend=file
# .env) runs no store export: the turso/ members stay conditional/optional
# and the run is green.
setup_home file-backend
run_backup file-backend env -u PM_AGG_STORE_EXPORT
if [[ $RC -eq 0 ]]; then
  ok "file-backend: script exited 0"
else
  fail "file-backend: expected exit 0, got $RC; log: $(cat "$TMP_ROOT/file-backend.log")"
fi
assert_member file-backend turso/agg_actions.json optional missing
if grep -q 'remote store export not applicable' "$TMP_ROOT/file-backend.log"; then
  ok "file-backend: log names the skipped store export"
else
  fail "file-backend: log does not name the skipped export: $(cat "$TMP_ROOT/file-backend.log")"
fi

# --- turso backend, export off: not applicable ----------------------------------
setup_home turso-backend-off
printf 'PM_AGG_STORE_BACKEND=turso\n' >"$RUN_HOME/.local/state/pm-aggregator/.env"
run_backup turso-backend-off
if [[ $RC -eq 0 ]]; then
  ok "turso-backend-off: script exited 0"
else
  fail "turso-backend-off: expected exit 0, got $RC; log: $(cat "$TMP_ROOT/turso-backend-off.log")"
fi
assert_member turso-backend-off turso/agg_actions.json optional missing

# --- Turso exporter stages every required table, no credentials in fixtures ---
setup_home turso-export
EXPORTER="$TMP_ROOT/turso-fixture-exporter"
cat >"$EXPORTER" <<'STUBEOF'
#!/usr/bin/env bash
set -eu
[[ "$1" == --output-dir && $# == 2 ]]
mkdir -p "$2"
for table in agg_actions agg_activity_ingestion agg_activity_gaps agg_usage_snapshots agg_store_documents alerts_incidents alerts_incident_events alerts_push_subscriptions alerts_notification_sends orch_runs push_endpoints push_preferences push_item_stages push_item_stage_events push_registry_meta; do
  printf '[]' >"$2/$table.json"
done
STUBEOF
chmod +x "$EXPORTER"
PATH="$BIN:$PATH" HOME="$RUN_HOME" BWS_ACCESS_TOKEN=fake-token \
  RCLONE_STUB_DIR="$TMP_ROOT/turso-export/rclone-store" \
  RCLONE_CALLS_LOG="$TMP_ROOT/turso-export/rclone-calls.log" \
  PM_DB_DUMP_SCRIPT="$DUMP_SCRIPT_ARG" PM_AGG_STORE_BACKEND=turso \
  PM_AGG_TURSO_EXPORT_BIN="$EXPORTER" \
  bash "$SCRIPT" 2026-10-28 >"$TMP_ROOT/turso-export.log" 2>&1
RC=$?
if [[ $RC -eq 0 ]]; then ok "turso-export: completed"; else fail "turso-export: rc=$RC $(cat "$TMP_ROOT/turso-export.log")"; fi
assert_member turso-export turso/agg_actions.json required present
assert_member turso-export turso/alerts_push_subscriptions.json required present
assert_member turso-export turso/orch_runs.json required present
assert_member turso-export turso/push_endpoints.json optional present

setup_home turso-missing
PATH="$BIN:$PATH" HOME="$RUN_HOME" BWS_ACCESS_TOKEN=fake-token \
  RCLONE_STUB_DIR="$TMP_ROOT/turso-missing/rclone-store" \
  RCLONE_CALLS_LOG="$TMP_ROOT/turso-missing/rclone-calls.log" \
  PM_DB_DUMP_SCRIPT="$DUMP_SCRIPT_ARG" PM_AGG_STORE_BACKEND=turso \
  PM_AGG_TURSO_EXPORT_BIN=/nonexistent/turso-exporter \
  bash "$SCRIPT" 2026-10-28 >"$TMP_ROOT/turso-missing.log" 2>&1
RC=$?
if [[ $RC -ne 0 ]] && no_upload turso-missing; then ok "turso-missing: fails without uploading"; else fail "turso-missing: did not fail closed"; fi

if ((failures > 0)); then
  echo "pm-dashboard-backup manifest tests: $failures failure(s)" >&2
  exit 1
fi
echo "pm-dashboard-backup manifest tests: all passed"
